from pathlib import Path

import spdx.license

def get_spdx_license_line(line: str) -> str | None:
    """Extract the SPDX identifier from a license comment line."""
    prefix = "SPDX-License-Identifier:"
    if line.startswith(prefix):
        return line[len(prefix) :].strip()
    return None

def validate_spdx_licenses(root_dir: Path) -> dict[str, list[str]]:
    """Validate SPDX license identifiers in all `.py` files under `root_dir`."""
    results: dict[str, list[str]] = {}
    for py_file in root_dir.rglob("*.py"):
        if py_file.is_file():
            lines = py_file.read_text(encoding="utf-8", errors="strict").splitlines()
            identifiers = [
                get_spdx_license_line(line) for line in lines
            ]
            if identifiers:
                first_id = identifiers[0].strip()
                if first_id and first_id.upper() not in spdx.license.LICENSES:
                    results[str(py_file)] = [f"Invalid SPDX tag: {first_id}"]
            elif identifiers:
                results[str(py_file)] = ["Missing SPDX-License-Identifier prefix"]
    return results
```

