from dataclasses import dataclass
from pathlib import Path
import ast


@dataclass(slots=True, frozen=True)
class ImportAlias:
    """Immutable record of a single imported module name and its local alias."""
    module: str
    alias: str


@dataclass(slots=True, frozen=True)
class SourceImports:
    """Complete import mapping extracted from a Python source file."""
    imports: tuple[ImportAlias, ...]


def extract_imports_from_source(source_text: str) -> SourceImports:
    """Parse source text and extract all top-level import statements."""
    tree = ast.parse(source_text)
    imports: list[ImportAlias] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.append(ImportAlias(module=alias.name, alias=alias.asname or alias.name))
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            if node.names:
                for alias in node.names:
                    a = alias.asname or alias.name
                    imports.append(ImportAlias(module=module, alias=a))
    return SourceImports(imports=tuple(sorted(imports, key=lambda i: (i.module, i.alias))))
```

